// Generate HTML report
const summary = $('Fetch Daily Summary').first().json;
const lowAttendance = $('Fetch Low Attendance').first().json;

const html = `
<!DOCTYPE html>
<html>
<head>
  <style>
    body { font-family: Arial, sans-serif; margin: 20px; }
    h1 { color: #1a365d; }
    .stat-box { display: inline-block; padding: 15px; margin: 10px; background: #f0f4f8; border-radius: 8px; }
    .stat-value { font-size: 24px; font-weight: bold; color: #2b6cb0; }
    table { width: 100%; border-collapse: collapse; margin-top: 20px; }
    th, td { border: 1px solid #ddd; padding: 10px; text-align: left; }
    th { background: #2b6cb0; color: white; }
    .critical { background: #fed7d7; }
  </style>
</head>
<body>
  <h1>📊 Daily Attendance Report - ${summary.date}</h1>

  <div class="stat-box">
    <div>Total Classes</div>
    <div class="stat-value">${summary.total_classes}</div>
  </div>
  <div class="stat-box">
    <div>Present</div>
    <div class="stat-value">${summary.total_present}</div>
  </div>
  <div class="stat-box">
    <div>Absent</div>
    <div class="stat-value">${summary.total_absent}</div>
  </div>
  <div class="stat-box">
    <div>Average Rate</div>
    <div class="stat-value">${summary.average_attendance_rate}%</div>
  </div>

  <h2>⚠️ Students Below 75% Attendance (${lowAttendance.count})</h2>
  <table>
    <tr><th>Name</th><th>Roll</th><th>Subject</th><th>Attendance</th></tr>
    ${lowAttendance.students.slice(0, 20).map(s => 
      `<tr class="${s.attendance_percentage < 60 ? 'critical' : ''}"><td>${s.student_name}</td><td>${s.roll_number}</td><td>${s.subject_name}</td><td>${s.attendance_percentage}%</td></tr>`
    ).join('')}
  </table>
</body>
</html>
`;

return [{ json: { html, summary, lowAttendance } }];
